// =============================================================================
// PREPARE GEMINI INPUT - With Hardcoded Immutable Criteria
// Builds properly escaped JSON body for Gemini API
// =============================================================================

const MSA_CRITERIA = [
  { id: "msa_1", metric: "Population Size", threshold: ">400,000" },
  { id: "msa_2", metric: "Population Growth", threshold: ">1% annual" },
  { id: "msa_3", metric: "Employment Growth", threshold: ">1% annual" },
  { id: "msa_4", metric: "Income Growth", threshold: ">2% annual" },
  { id: "msa_5", metric: "In-Migration", threshold: "Positive net migration" },
  { id: "msa_6", metric: "Job Diversity", threshold: "No single industry >25%" },
  { id: "msa_7", metric: "Environmental Risk", threshold: "Low flood/fire/hurricane risk" },
  { id: "msa_8", metric: "Unemployment Rate", threshold: "<6%" },
  { id: "msa_9", metric: "Apartment Vacancy Rate", threshold: "4-6% GOLDILOCKS", goldilocks: true },
  { id: "msa_10", metric: "Cap Rate Spread", threshold: ">200 bps above Treasury" },
  { id: "msa_11", metric: "Homeowner Vacancy", threshold: "<2%" },
  { id: "msa_12", metric: "Multifamily Permits", threshold: "<2% of stock annually" },
  { id: "msa_13", metric: "Absorption Rate", threshold: "<18 months" },
  { id: "msa_14", metric: "Landlord-Friendly Laws", threshold: "No rent control, <60 day eviction" },
  { id: "msa_15", metric: "Affordability Index", threshold: "Rent <30% of income" },
  { id: "msa_16", metric: "Proximity to Tier 1 MSA", threshold: "<200 miles OR is Tier 1" }
];

const SUBMARKET_CRITERIA = [
  { id: "sub_1", metric: "Crime Rate", threshold: "<MSA average" },
  { id: "sub_2", metric: "School Ratings", threshold: ">5/10 GreatSchools" },
  { id: "sub_3", metric: "Goldilocks Amenities", threshold: "1-2mi to retail GOLDILOCKS", goldilocks: true },
  { id: "sub_4", metric: "Proximity to Schools", threshold: "<2 miles" },
  { id: "sub_5", metric: "Transport Access", threshold: "1-2mi GOLDILOCKS", goldilocks: true },
  { id: "sub_6", metric: "Transport Avoidance", threshold: ">0.5mi from highway/airport" },
  { id: "sub_7", metric: "Path of Growth", threshold: "On development corridor" },
  { id: "sub_8", metric: "Zoning Protections", threshold: "Residential/MF zoning" },
  { id: "sub_9", metric: "Renter Density", threshold: ">50% renters", context_aware: true },
  { id: "sub_10", metric: "Proximity to MF Assets", threshold: "3+ comps within 1mi" },
  { id: "sub_11", metric: "Cluster Growth Potential", threshold: "Land available" },
  { id: "sub_12", metric: "Taxes and Fees", threshold: "<2% of value annually" },
  { id: "sub_13", metric: "Historical Appreciation", threshold: ">3% annually" },
  { id: "sub_14", metric: "Government Volatility", threshold: "Stable governance" }
];

const formatCriteria = (criteria) => criteria.map(c => c.id + ": " + c.metric + " | " + c.threshold).join("; ");

const researchNode = $('Perplexity Research').first();
let researchData = "Research data not available";
try {
  const content = researchNode.json.choices?.[0]?.message?.content;
  if (content) researchData = content;
} catch (e) {}

const contextNode = $('Parse Context Docs').first();
const contextDocs = contextNode.json.context_text || "None";

const inputNode = $('Extract Input Data').first();
const address = inputNode.json.address || "Address not provided";
const dealName = inputNode.json.deal_name || "Unnamed Deal";

const promptText = `Evaluate this property for multifamily investment. Return ONLY a JSON array with exactly 30 objects.

ADDRESS: ${address}

CRITERIA (evaluate all 30):
MSA: ${formatCriteria(MSA_CRITERIA)}
SUB: ${formatCriteria(SUBMARKET_CRITERIA)}

RESEARCH: ${researchData}

CONTEXT DOCS: ${contextDocs}

RULES:
1. Status must be GREEN, YELLOW, or RED only
2. Reasoning must be 20-50 chars (concise)
3. GOLDILOCKS: vacancy 4-6%=GREEN, <3%=YELLOW, >7%=RED; amenities 1-2mi=GREEN
4. Return valid JSON array, no markdown

FORMAT: [{"id":"msa_1","metric":"Population Size","threshold":">400,000","value":"2.3M","status":"GREEN","reasoning":"Austin MSA exceeds threshold","source":"Census","override_applied":false,"override_document":null},...]

Output exactly 30 items: msa_1-msa_16, sub_1-sub_14`;

const geminiRequestBody = {
  contents: [{role: "user", parts: [{text: promptText}]}],
  generationConfig: {temperature: 0.1, maxOutputTokens: 32768, responseMimeType: "application/json"}
};

return {
  gemini_request_body: geminiRequestBody,
  address: address,
  deal_name: dealName
};

// Extract and validate the 30-point heat map JSON from Gemini response
const geminiResponse = $input.first().json;

let responseText;
try {
  responseText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!responseText) {
    throw new Error('No text content in Gemini response');
  }
} catch (e) {
  throw new Error('Failed to extract Gemini response: ' + e.message);
}

let heatMapJson;
try {
  heatMapJson = JSON.parse(responseText);
} catch (e) {
  const jsonMatch = responseText.match(/\[\s*\{[\s\S]*\}\s*\]/);
  if (jsonMatch) {
    heatMapJson = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Failed to parse JSON: ' + e.message);
  }
}

if (!Array.isArray(heatMapJson)) {
  throw new Error('Heat map must be an array');
}

if (heatMapJson.length !== 30) {
  throw new Error('Heat map must contain exactly 30 items, got ' + heatMapJson.length);
}

const requiredFields = ['id', 'metric', 'threshold', 'value', 'status', 'reasoning', 'source'];
const validStatuses = ['GREEN', 'YELLOW', 'RED'];

for (let i = 0; i < heatMapJson.length; i++) {
  const item = heatMapJson[i];
  for (const field of requiredFields) {
    if (!(field in item)) {
      throw new Error('Item ' + i + ' missing field: ' + field);
    }
  }
  if (!validStatuses.includes(item.status)) {
    throw new Error('Item ' + i + ' has invalid status: ' + item.status);
  }
}

const greenCount = heatMapJson.filter(i => i.status === 'GREEN').length;
const yellowCount = heatMapJson.filter(i => i.status === 'YELLOW').length;
const redCount = heatMapJson.filter(i => i.status === 'RED').length;

let recommendation;
if (redCount > 5) {
  recommendation = 'NO-GO';
} else if (redCount >= 3) {
  recommendation = 'CAUTION';
} else {
  recommendation = 'PROCEED';
}

return {
  heat_map: heatMapJson,
  validation_passed: true,
  total_items: heatMapJson.length,
  green_count: greenCount,
  yellow_count: yellowCount,
  red_count: redCount,
  recommendation: recommendation,
  address: $('Extract Input Data').first().json.address,
  deal_name: $('Extract Input Data').first().json.deal_name
};

const data = $input.first().json;
const heatMap = data.heat_map;
const dealName = data.deal_name;
const address = data.address;
const recommendation = data.recommendation;
const greenCount = data.green_count;
const yellowCount = data.yellow_count;
const redCount = data.red_count;

const statusColors = { 'GREEN': '#22c55e', 'YELLOW': '#eab308', 'RED': '#ef4444' };
const statusBgColors = { 'GREEN': '#dcfce7', 'YELLOW': '#fef9c3', 'RED': '#fee2e2' };
const recColors = {
  'PROCEED': { bg: '#dcfce7', text: '#166534', label: 'PROCEED' },
  'CAUTION': { bg: '#fef9c3', text: '#854d0e', label: 'CAUTION' },
  'NO-GO': { bg: '#fee2e2', text: '#991b1b', label: 'NO-GO' }
};
const rec = recColors[recommendation] || recColors['CAUTION'];

const msaCriteria = heatMap.filter(c => c.id.startsWith('msa_'));
const subCriteria = heatMap.filter(c => c.id.startsWith('sub_'));

const buildRow = (item) => '<tr style="border-bottom: 1px solid #e5e7eb;"><td style="padding: 12px 8px; font-weight: 500;">' + item.id + '</td><td style="padding: 12px 8px;">' + item.metric + '</td><td style="padding: 12px 8px; color: #6b7280;">' + item.threshold + '</td><td style="padding: 12px 8px;">' + item.value + '</td><td style="padding: 12px 8px;"><span style="display: inline-block; padding: 4px 12px; border-radius: 9999px; font-size: 12px; font-weight: 600; background: ' + statusBgColors[item.status] + '; color: ' + statusColors[item.status] + ';">' + item.status + '</span></td><td style="padding: 12px 8px; font-size: 13px; color: #4b5563; max-width: 300px;">' + item.reasoning + '</td></tr>';

const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { font-family: -apple-system, BlinkMacSystemFont, sans-serif; color: #1f2937; line-height: 1.5; padding: 40px; } .header { text-align: center; margin-bottom: 40px; padding-bottom: 20px; border-bottom: 2px solid #e5e7eb; } .header h1 { font-size: 28px; color: #111827; margin-bottom: 8px; } .header p { color: #6b7280; font-size: 16px; } .summary { display: flex; justify-content: center; gap: 24px; margin: 30px 0; } .summary-card { padding: 20px 30px; border-radius: 12px; text-align: center; } .summary-card .number { font-size: 36px; font-weight: 700; } .summary-card .label { font-size: 14px; color: #6b7280; margin-top: 4px; } .recommendation { text-align: center; margin: 30px 0; padding: 20px; border-radius: 12px; } .recommendation .label { font-size: 24px; font-weight: 700; } .section { margin: 40px 0; } .section h2 { font-size: 20px; color: #374151; margin-bottom: 16px; padding-bottom: 8px; border-bottom: 2px solid #e5e7eb; } table { width: 100%; border-collapse: collapse; font-size: 14px; } th { text-align: left; padding: 12px 8px; background: #f9fafb; font-weight: 600; color: #374151; border-bottom: 2px solid #e5e7eb; } .footer { margin-top: 40px; padding-top: 20px; border-top: 2px solid #e5e7eb; text-align: center; color: #9ca3af; font-size: 12px; }</style></head><body><div class="header"><h1>' + dealName + '</h1><p>' + address + '</p><p style="margin-top: 8px; font-size: 12px;">Generated: ' + new Date().toISOString().split('T')[0] + '</p></div><div class="summary"><div class="summary-card" style="background: #dcfce7;"><div class="number" style="color: #166534;">' + greenCount + '</div><div class="label">GREEN</div></div><div class="summary-card" style="background: #fef9c3;"><div class="number" style="color: #854d0e;">' + yellowCount + '</div><div class="label">YELLOW</div></div><div class="summary-card" style="background: #fee2e2;"><div class="number" style="color: #991b1b;">' + redCount + '</div><div class="label">RED</div></div></div><div class="recommendation" style="background: ' + rec.bg + ';"><div class="label" style="color: ' + rec.text + ';">' + rec.label + '</div></div><div class="section"><h2>MSA Criteria (' + msaCriteria.length + ' points)</h2><table><thead><tr><th>ID</th><th>Metric</th><th>Threshold</th><th>Value</th><th>Status</th><th>Reasoning</th></tr></thead><tbody>' + msaCriteria.map(buildRow).join('') + '</tbody></table></div><div class="section"><h2>Sub-Market Criteria (' + subCriteria.length + ' points)</h2><table><thead><tr><th>ID</th><th>Metric</th><th>Threshold</th><th>Value</th><th>Status</th><th>Reasoning</th></tr></thead><tbody>' + subCriteria.map(buildRow).join('') + '</tbody></table></div><div class="footer"><p>AI Multifamily Deep Research Engine | 30-Point Heat Map Analysis</p></div></body></html>';

return {
  html: html,
  deal_name: dealName,
  address: address,
  recommendation: recommendation,
  heat_map: heatMap,
  green_count: greenCount,
  yellow_count: yellowCount,
  red_count: redCount
};
